def IsMaximalClosedIdeal (I : Set A) : Prop :=
  IsClosedIdeal 𝕜 I ∧ I ≠ Set.univ ∧
  ∀ J : Set A, IsClosedIdeal 𝕜 J → I ⊆ J → J = I ∨ J = Set.univ

